def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    op_c = sum(1 for a in op if a == 'C')

    # Pure defector: never cooperated
    if n >= 2 and op_c == 0:
        return 'D'

    # Recent opponent defections: if last 4 are all D, defect
    if n >= 4 and all(a == 'D' for a in op[-4:]):
        return 'D'

    # Exploit unconditional cooperators
    if n >= 4 and all(a == 'C' for a in op[-4:]):
        my_recent_def = sum(1 for a in me[-4:] if a == 'D')
        if my_recent_def >= 2:
            return 'D'
        elif my_recent_def == 1:
            if me[-1] == 'D' and op[-1] == 'C':
                if rng.random() < 0.3:
                    return 'D'
        else:
            if rng.random() < 0.1:
                return 'D'

    last_me = me[-1]
    last_op = op[-1]

    if last_op == 'D':
        # Consecutive defections
        if n >= 2 and op[-2] == 'D':
            return 'D'
        if last_me == 'D':
            return 'C'
        # Forgive if opponent mostly cooperative
        if n >= 5 and op_c >= n * 0.7:
            if rng.random() < 0.3:
                return 'C'
        return 'D'
    else:
        # last_op == 'C'
        if n >= 99:
            return 'D'
        if n >= 90 and op_c >= n - 2:
            return 'D' if rng.random() < 0.7 else 'C'
        if n >= 85 and op_c >= n - 5:
            return 'D' if rng.random() < 0.3 else 'C'
        return 'C'
